package com.jhazewindus.spinthatboss;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Wheel names and the corresponding names emitted by RuneLite's Loot Tracker. */
final class BossCatalog
{
	private static final List<String> BOSSES = Arrays.asList(
		"Abyssal Sire", "Alchemical Hydra", "Amoxliatl", "Araxxor", "Artio", "Barrows",
		"Brutus", "Bryophyta", "Callisto", "Cal'varion", "Cerberus", "Chambers of Xeric",
		"Chaos Elemental", "Chaos Fanatic", "Commander Zilyana", "Corporeal Beast",
		"Crazy Archaeologist", "Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme",
		"Deranged Archaeologist", "Doom of Mokhaiotl", "Duke Sucellus", "Fortis Colosseum",
		"Fractured Archive", "General Graardor", "Giant Mole", "Grotesque Guardians",
		"Guardians of the Rift", "Hespori", "Kalphite Queen", "King Black Dragon", "Kraken",
		"Kree'arra", "K'ril Tsutsaroth", "Mad Angel", "Maggot King", "Moons of Peril",
		"Nex", "Nightmare", "Obor", "Phantom Muspah", "Phosani's Nightmare",
		"Sarachnis", "Scorpia", "Scurrius", "Shellbane Gryphon", "Skotizo", "Spindel",
		"Tempoross", "The Corrupted Gauntlet", "The Gauntlet", "The Hueycoatl",
		"The Leviathan", "The Royal Titans", "The Whisperer", "Theatre of Blood",
		"Thermonuclear Smoke Devil", "Tombs of Amascut", "Vardorvis", "Venenatis",
		"Vet'ion", "Vorkath", "Wintertodt", "Yama", "Zalcano", "Zulrah"
	);
	private static final Map<String, String> LOOT_NAMES = new LinkedHashMap<>();

	static
	{
		for (String boss : BOSSES)
		{
			alias(boss, boss);
		}
		alias("Lunar Chest", "Moons of Peril");
		alias("Barrows Chest", "Barrows");
		alias("Dusk", "Grotesque Guardians");
		alias("Crystalline Hunllef", "The Gauntlet");
		alias("Corrupted Hunllef", "The Corrupted Gauntlet");
		alias("Gauntlet", "The Gauntlet");
		alias("Corrupted Gauntlet", "The Corrupted Gauntlet");
		alias("Reward pool (Tempoross)", "Tempoross");
		alias("Supply crate (Wintertodt)", "Wintertodt");
		alias("Reward cart (Wintertodt)", "Wintertodt");
		alias("Branda the Fire Queen", "The Royal Titans");
		alias("Eldric the Ice King", "The Royal Titans");
	}

	private BossCatalog()
	{
	}

	static String defaultPool()
	{
		return String.join(", ", BOSSES);
	}

	static List<String> bosses()
	{
		return Collections.unmodifiableList(BOSSES);
	}

	static boolean matchesLoot(String wheelBoss, String lootName)
	{
		if (wheelBoss == null || lootName == null)
		{
			return false;
		}
		String canonical = LOOT_NAMES.getOrDefault(lootName.trim().toLowerCase(Locale.ROOT), lootName);
		return wheelBoss.trim().equalsIgnoreCase(canonical);
	}

	static String wiseOldManMetric(String boss)
	{
		String metric = boss.trim().toLowerCase(Locale.ROOT).replace("'", "")
			.replace(' ', '_').replace('-', '_');
		switch (metric)
		{
			case "barrows":
				return "barrows_chests";
			case "moons_of_peril":
				return "lunar_chests";
			case "fractured_archive":
				return "the_fractured_archive";
			default:
				return metric;
		}
	}

	private static void alias(String lootName, String boss)
	{
		LOOT_NAMES.put(lootName.toLowerCase(Locale.ROOT), boss);
	}
}

package com.jhazewindus.spinthatboss;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class BossWheel
{
	private static final SecureRandom RANDOM = new SecureRandom();

	private BossWheel()
	{
	}

	static List<String> parsePool(String value)
	{
		List<String> pool = new ArrayList<>();
		if (value == null)
		{
			return pool;
		}

		for (String raw : value.split(","))
		{
			String boss = raw.trim();
			if (!boss.isEmpty() && pool.stream().noneMatch(existing -> existing.equalsIgnoreCase(boss)))
			{
				pool.add(boss);
			}
		}
		return pool;
	}

	static List<String> shuffledBag(List<String> pool, String previousBoss)
	{
		List<String> bag = new ArrayList<>(pool);
		Collections.shuffle(bag, RANDOM);
		if (bag.size() > 1 && bag.get(0).equalsIgnoreCase(previousBoss))
		{
			Collections.swap(bag, 0, 1);
		}
		return bag;
	}
}

package com.jhazewindus.spinthatboss;

import net.runelite.client.party.messages.PartyMemberMessage;

public class MatchMessage extends PartyMemberMessage
{
	public String operation;
	public MatchState state;
	public String matchId;
	public String boss;
	public int legNumber;
	public PlayerProgress memberProgress;
}

package com.jhazewindus.spinthatboss;

import java.util.List;
import java.util.Objects;
import java.util.function.Predicate;

/** Pure match rules shared by local events, saved state and party messages. */
final class MatchRules
{
	private MatchRules()
	{
	}

	static boolean validName(String name)
	{
		return name != null && !name.trim().isEmpty() && !"<unknown>".equals(name);
	}

	static boolean validProgress(PlayerProgress progress)
	{
		return progress != null && validName(progress.memberName)
			&& progress.kills >= 0 && progress.currentLegKills >= 0
			&& progress.totalDropValue >= 0 && progress.currentLegDropValue >= 0
			&& progress.fastestKillMillis >= 0 && progress.mostValuableDrop >= 0
			&& validStrings(progress.rareDrops) && validStrings(progress.currentLegRareDrops);
	}

	static boolean validState(MatchState state)
	{
		return state != null && validName(state.matchId) && validName(state.hostName)
			&& state.partyId != 0 && state.legNumber >= 0
			&& state.killsPerMember > 0 && state.valueTarget > 0
			&& validStrings(state.bossPool) && !state.bossPool.isEmpty()
			&& validStrings(state.remainingBosses) && state.bossPool.containsAll(state.remainingBosses)
			&& validStrings(state.memberNames) && !state.memberNames.isEmpty()
			&& validStrings(state.history) && state.progress != null
			&& state.progress.entrySet().stream().allMatch(e -> validName(e.getKey()) && validProgress(e.getValue()))
			&& (state.legNumber == 0 ? state.currentBoss == null : state.bossPool.contains(state.currentBoss))
			&& state.goalType != null;
	}

	static boolean acceptsState(MatchState current, MatchState incoming, long partyId, String sender)
	{
		if (!validState(incoming) || incoming.partyId != partyId || !sameName(sender, incoming.hostName))
		{
			return false;
		}
		if (current == null || current.partyId != partyId)
		{
			return true;
		}
		if (!Objects.equals(current.matchId, incoming.matchId))
		{
			// Rejoiners may have missed the host ending a match before starting the next.
			return current.ended || sameName(current.hostName, incoming.hostName);
		}
		return sameName(current.hostName, incoming.hostName)
			&& incoming.legNumber >= current.legNumber
			&& (!current.ended || incoming.ended)
			&& (incoming.ended || incoming.legNumber != current.legNumber || !current.legComplete || incoming.legComplete);
	}

	static boolean acceptsProgress(MatchState state, long partyId, String senderKey, MatchMessage message)
	{
		return state != null && !state.ended && state.partyId == partyId
			&& Objects.equals(state.matchId, message.matchId) && state.legNumber == message.legNumber
			&& sameName(state.currentBoss, message.boss) && state.memberNames.contains(senderKey)
			&& validProgress(message.memberProgress);
	}

	static PlayerProgress retainLocalProgress(MatchState current, MatchState incoming, String localKey)
	{
		if (current == null || !Objects.equals(current.matchId, incoming.matchId)
			|| current.legNumber != incoming.legNumber || !incoming.memberNames.contains(localKey))
		{
			return null;
		}
		PlayerProgress local = current.progress.get(localKey);
		if (validProgress(local))
		{
			// The local client owns its loot counters; a host snapshot may lag behind them.
			incoming.progress.put(localKey, local);
			updateGoal(incoming);
			return local;
		}
		return null;
	}

	static void updateGoal(MatchState state)
	{
		if (state == null || state.ended || state.currentBoss == null || state.legComplete)
		{
			return;
		}
		Predicate<PlayerProgress> goal;
		boolean everyone;
		switch (state.goalType)
		{
			case "FIRST_RARE":
			case "EVERYONE_RARE":
				goal = p -> !p.currentLegRareDrops.isEmpty();
				everyone = "EVERYONE_RARE".equals(state.goalType);
				break;
			case "FIRST_PET":
			case "EVERYONE_PET":
				goal = p -> p.currentLegHasPet;
				everyone = "EVERYONE_PET".equals(state.goalType);
				break;
			case "FIRST_VALUE":
				goal = p -> p.currentLegDropValue >= state.valueTarget;
				everyone = false;
				break;
			case "FIRST_KILLS":
			case "KILLS_EACH":
				goal = p -> p.currentLegKills >= state.killsPerMember;
				everyone = "KILLS_EACH".equals(state.goalType);
				break;
			default:
				return;
		}
		Predicate<String> memberGoal = name -> state.progress.containsKey(name) && goal.test(state.progress.get(name));
		state.legComplete = !state.memberNames.isEmpty() && (everyone
			? state.memberNames.stream().allMatch(memberGoal)
			: state.memberNames.stream().anyMatch(memberGoal));
	}

	private static boolean validStrings(List<String> values)
	{
		return values != null && values.stream().allMatch(MatchRules::validName);
	}

	private static boolean sameName(String first, String second)
	{
		return first != null && second != null && first.trim().equalsIgnoreCase(second.trim());
	}
}

package com.jhazewindus.spinthatboss;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class MatchState
{
	public String matchId;
	public long partyId;
	public String hostName;
	public boolean ended;
	public int legNumber;
	public String currentBoss;
	public String goalType;
	public int killsPerMember;
	public long valueTarget;
	public String rareItems;
	public boolean legComplete;
	public List<String> bossPool = new ArrayList<>();
	public List<String> remainingBosses = new ArrayList<>();
	public List<String> memberNames = new ArrayList<>();
	public Map<String, PlayerProgress> progress = new LinkedHashMap<>();
	public List<String> history = new ArrayList<>();
}

package com.jhazewindus.spinthatboss;

import java.util.ArrayList;
import java.util.List;

public class PlayerProgress
{
	public String memberName;
	public int kills;
	public int currentLegKills;
	public long totalDropValue;
	public long currentLegDropValue;
	public boolean hasPet;
	public boolean currentLegHasPet;
	public int wiseOldManBaseline = -1;
	public String baselineBoss;
	public long fastestKillMillis;
	public String fastestKillBoss;
	public List<String> rareDrops = new ArrayList<>();
	public List<String> currentLegRareDrops = new ArrayList<>();
	public long mostValuableDrop;
	public String mostValuableDropName;
}

package com.jhazewindus.spinthatboss;

import java.util.ArrayList;
import java.util.List;

/** Choices made by the host before a run starts. */
final class RunSetup
{
	List<String> bosses = new ArrayList<>(BossCatalog.bosses());
	String goalType = "FIRST_KILLS";
	int killTarget = 25;
	long valueTarget = 100_000_000L;
	String rareItems = "Zulrah: Tanzanite fang | Magic fang | Serpentine visage | Jar of swamp";
}

package com.jhazewindus.spinthatboss;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("spin-that-boss")
public interface SpinThatBossConfig extends Config
{
	@ConfigItem(
		keyName = "wiseOldManBaseline",
		name = "Use Wise Old Man baselines",
		description = "Fetch each member's boss kill count when a new boss leg starts",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean wiseOldManBaseline()
	{
		return false;
	}
}

package com.jhazewindus.spinthatboss;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.text.ParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.PluginPanel;

final class SpinThatBossPanel extends PluginPanel
{
	private static final GoalChoice[] GOALS = {
		new GoalChoice("FIRST_KILLS", "First to kill target"),
		new GoalChoice("KILLS_EACH", "Everyone reaches kill target"),
		new GoalChoice("FIRST_VALUE", "First to loot-value target"),
		new GoalChoice("FIRST_RARE", "First to chosen rare drop"),
		new GoalChoice("EVERYONE_RARE", "Everyone gets chosen rare"),
		new GoalChoice("FIRST_PET", "First to pet"),
		new GoalChoice("EVERYONE_PET", "Everyone gets pet")
	};

	private final CardLayout cards = new CardLayout();
	private final JLabel partyLabel = new JLabel("Not in a RuneLite party", SwingConstants.CENTER);
	private final JLabel matchLabel = new JLabel("No run running", SwingConstants.CENTER);
	private final JLabel bossLabel = new JLabel("Current boss: —");
	private final JLabel goalLabel = new JLabel("Goal: —");
	private final JTextArea players = new JTextArea(8, 22);
	private final JTextArea history = new JTextArea(6, 22);
	private final JButton setupButton = new JButton("Setup run");
	private final JButton spinButton = new JButton("Spin the wheel");
	private final JButton endButton = new JButton("End run");
	private final JButton startButton = new JButton("Start run");
	private final JLabel setupStatus = new JLabel(" ");
	private final JTextField search = new JTextField();
	private final JPanel bossChoices = new JPanel();
	private final Map<String, JCheckBox> bossChecks = new LinkedHashMap<>();
	private final JComboBox<GoalChoice> goalChoice = new JComboBox<>(GOALS);
	private final JSpinner killTarget = new JSpinner(new SpinnerNumberModel(25, 1, Integer.MAX_VALUE, 1));
	private final JSpinner valueTarget = new JSpinner(new SpinnerNumberModel(100_000_000L, 1L, Long.MAX_VALUE, 1_000_000L));
	private final JPanel killRow = new JPanel(new BorderLayout(4, 2));
	private final JPanel valueRow = new JPanel(new BorderLayout(4, 2));
	private final JPanel rareRow = new JPanel(new BorderLayout(4, 2));
	private final JTextArea rareItems = new JTextArea(4, 20);
	private boolean inParty;
	private boolean setupVisible;

	SpinThatBossPanel(Consumer<RunSetup> start, Runnable spin, Runnable end, RunSetup initial)
	{
		super(false);
		setLayout(cards);
		setPreferredSize(new Dimension(250, 480));
		add(createRunView(spin, end), "run");
		add(createSetupView(start), "setup");
		applySetup(initial);
		cards.show(this, "run");
	}

	private JPanel createRunView(Runnable spin, Runnable end)
	{
		JPanel view = new JPanel(new BorderLayout(6, 6));
		view.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		JLabel title = new JLabel("Spin That Boss", SwingConstants.CENTER);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		JPanel header = new JPanel(new GridLayout(0, 1, 0, 4));
		header.add(title);
		header.add(partyLabel);
		header.add(matchLabel);
		header.add(bossLabel);
		header.add(goalLabel);
		view.add(header, BorderLayout.NORTH);

		players.setEditable(false);
		players.setLineWrap(true);
		players.setWrapStyleWord(true);
		history.setEditable(false);
		history.setLineWrap(true);
		history.setWrapStyleWord(true);
		JPanel details = new JPanel(new BorderLayout(4, 4));
		details.add(new JLabel("Party cards"), BorderLayout.NORTH);
		details.add(new JScrollPane(players), BorderLayout.CENTER);
		JPanel historyPanel = new JPanel(new BorderLayout(4, 4));
		historyPanel.add(new JLabel("Run history"), BorderLayout.NORTH);
		historyPanel.add(new JScrollPane(history), BorderLayout.CENTER);
		JPanel center = new JPanel(new GridLayout(2, 1, 0, 8));
		center.add(details);
		center.add(historyPanel);
		view.add(center, BorderLayout.CENTER);

		setupButton.addActionListener(e -> openSetup());
		spinButton.addActionListener(e -> spin.run());
		endButton.addActionListener(e -> end.run());
		JPanel actions = new JPanel(new GridLayout(0, 1, 0, 4));
		actions.add(setupButton);
		actions.add(spinButton);
		actions.add(endButton);
		view.add(actions, BorderLayout.SOUTH);
		return view;
	}

	private JPanel createSetupView(Consumer<RunSetup> start)
	{
		JPanel view = new JPanel(new BorderLayout(6, 6));
		view.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		JLabel title = new JLabel("Setup run", SwingConstants.CENTER);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.add(title);
		top.add(new JLabel("Choose bosses for the wheel"));
		search.setToolTipText("Search bosses");
		top.add(search);
		JPanel selection = new JPanel(new GridLayout(1, 2, 4, 0));
		JButton selectAll = new JButton("Select all");
		selectAll.addActionListener(e -> bossChecks.values().forEach(check -> check.setSelected(true)));
		JButton clear = new JButton("Clear all");
		clear.addActionListener(e -> bossChecks.values().forEach(check -> check.setSelected(false)));
		selection.add(selectAll);
		selection.add(clear);
		top.add(selection);

		bossChoices.setLayout(new BoxLayout(bossChoices, BoxLayout.Y_AXIS));
		for (String boss : BossCatalog.bosses())
		{
			JCheckBox check = new JCheckBox(boss);
			bossChecks.put(boss, check);
			bossChoices.add(check);
		}
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override public void insertUpdate(DocumentEvent e) { filterBosses(); }
			@Override public void removeUpdate(DocumentEvent e) { filterBosses(); }
			@Override public void changedUpdate(DocumentEvent e) { filterBosses(); }
		});
		JScrollPane bossScroll = new JScrollPane(bossChoices);
		bossScroll.setPreferredSize(new Dimension(220, 200));

		JPanel options = new JPanel();
		options.setLayout(new BoxLayout(options, BoxLayout.Y_AXIS));
		options.add(new JLabel("Goal for each boss"));
		options.add(goalChoice);
		killRow.add(new JLabel("Kills needed"), BorderLayout.NORTH);
		killRow.add(killTarget, BorderLayout.CENTER);
		valueRow.add(new JLabel("Loot value needed (GP)"), BorderLayout.NORTH);
		valueRow.add(valueTarget, BorderLayout.CENTER);
		rareRow.add(new JLabel("Rare drops (Boss: Item | Item)"), BorderLayout.NORTH);
		rareItems.setLineWrap(true);
		rareItems.setWrapStyleWord(true);
		rareRow.add(new JScrollPane(rareItems), BorderLayout.CENTER);
		options.add(killRow);
		options.add(valueRow);
		options.add(rareRow);
		goalChoice.addActionListener(e -> updateGoalFields());
		JPanel middle = new JPanel(new BorderLayout(4, 6));
		middle.add(bossScroll, BorderLayout.CENTER);
		middle.add(options, BorderLayout.SOUTH);
		JPanel content = new JPanel(new BorderLayout(4, 6));
		content.add(top, BorderLayout.NORTH);
		content.add(middle, BorderLayout.CENTER);
		view.add(new JScrollPane(content), BorderLayout.CENTER);

		startButton.addActionListener(e -> {
			try
			{
				if (killRow.isVisible())
				{
					killTarget.commitEdit();
				}
				if (valueRow.isVisible())
				{
					valueTarget.commitEdit();
				}
			}
			catch (ParseException ex)
			{
				setupStatus.setText("Enter a valid target number.");
				return;
			}
			RunSetup setup = selectedSetup();
			if (setup.bosses.isEmpty())
			{
				setupStatus.setText("Select at least one boss.");
				return;
			}
			if (!inParty)
			{
				setupStatus.setText("Join a RuneLite party first.");
				return;
			}
			setupStatus.setText(" ");
			start.accept(setup);
		});
		JButton back = new JButton("Back");
		back.addActionListener(e -> closeSetup());
		JPanel bottom = new JPanel(new GridLayout(0, 1, 0, 3));
		bottom.add(setupStatus);
		bottom.add(startButton);
		bottom.add(back);
		view.add(bottom, BorderLayout.SOUTH);
		return view;
	}

	private void filterBosses()
	{
		String query = search.getText().trim().toLowerCase(Locale.ROOT);
		bossChecks.forEach((boss, check) -> check.setVisible(boss.toLowerCase(Locale.ROOT).contains(query)));
		bossChoices.revalidate();
		bossChoices.repaint();
	}

	private void updateGoalFields()
	{
		GoalChoice choice = (GoalChoice) goalChoice.getSelectedItem();
		String id = choice == null ? "FIRST_KILLS" : choice.id;
		killRow.setVisible("FIRST_KILLS".equals(id) || "KILLS_EACH".equals(id));
		valueRow.setVisible("FIRST_VALUE".equals(id));
		rareRow.setVisible("FIRST_RARE".equals(id) || "EVERYONE_RARE".equals(id));
	}

	private RunSetup selectedSetup()
	{
		RunSetup setup = new RunSetup();
		setup.bosses = new ArrayList<>();
		bossChecks.forEach((boss, check) -> { if (check.isSelected()) { setup.bosses.add(boss); } });
		setup.goalType = ((GoalChoice) goalChoice.getSelectedItem()).id;
		setup.killTarget = ((Number) killTarget.getValue()).intValue();
		setup.valueTarget = ((Number) valueTarget.getValue()).longValue();
		setup.rareItems = rareItems.getText().trim();
		return setup;
	}

	private void applySetup(RunSetup setup)
	{
		bossChecks.forEach((boss, check) -> check.setSelected(setup.bosses.contains(boss)));
		for (int i = 0; i < goalChoice.getItemCount(); i++)
		{
			if (goalChoice.getItemAt(i).id.equals(setup.goalType))
			{
				goalChoice.setSelectedIndex(i);
				break;
			}
		}
		killTarget.setValue(Math.max(1, setup.killTarget));
		valueTarget.setValue(Math.max(1L, setup.valueTarget));
		rareItems.setText(setup.rareItems);
		updateGoalFields();
	}

	private void openSetup()
	{
		setupVisible = true;
		setupStatus.setText(" ");
		cards.show(this, "setup");
	}

	private void closeSetup()
	{
		setupVisible = false;
		cards.show(this, "run");
	}

	void showState(MatchState state, String playerSummary, String matchHistory, boolean inParty, boolean isHost)
	{
		this.inParty = inParty;
		partyLabel.setText(inParty ? "RuneLite party connected" : "Join a party in RuneLite's Party panel");
		if (state == null)
		{
			matchLabel.setText("No run running");
			bossLabel.setText("Current boss: —");
			goalLabel.setText("Goal: —");
			players.setText("Set up a run to choose your bosses and goal.");
			history.setText("");
			setupButton.setEnabled(true);
			spinButton.setEnabled(false);
			endButton.setEnabled(false);
			return;
		}

		matchLabel.setText(state.ended ? "Run ended" : "Run active · leg " + state.legNumber);
		bossLabel.setText("Current boss: " + (state.currentBoss == null ? "—" : state.currentBoss));
		goalLabel.setText(goalDescription(state));
		players.setText(playerSummary);
		history.setText(matchHistory);
		setupButton.setEnabled(state.ended);
		spinButton.setEnabled(inParty && isHost && !state.ended && (state.currentBoss == null || state.legComplete));
		endButton.setEnabled(inParty && isHost && !state.ended);
		if (!state.ended && setupVisible)
		{
			closeSetup();
		}
	}

	private static String goalDescription(MatchState state)
	{
		switch (state.goalType)
		{
			case "EVERYONE_RARE": return "Goal: everyone gets a chosen rare drop";
			case "FIRST_RARE": return "Goal: first player gets a chosen rare drop";
			case "FIRST_PET": return "Goal: first player gets a pet";
			case "EVERYONE_PET": return "Goal: everyone gets a pet";
			case "FIRST_KILLS": return "Goal: first player reaches " + state.killsPerMember + " kills";
			case "KILLS_EACH": return "Goal: everyone reaches " + state.killsPerMember + " kills";
			case "FIRST_VALUE": return "<html>Goal: first to " + String.format(Locale.ROOT, "%,d", state.valueTarget)
				+ " GP<br>in drops</html>";
			default: return "Goal: —";
		}
	}

	private static final class GoalChoice
	{
		private final String id;
		private final String label;

		private GoalChoice(String id, String label)
		{
			this.id = id;
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}
}

